package com.mycompany.greenbasket;
import java.io.*;import jakarta.servlet.*;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;
@WebServlet("/FarmerRegistrationServlet")
public class FarmerRegistrationServlet extends HttpServlet{protected void doPost(HttpServletRequest req,HttpServletResponse res)throws ServletException,IOException{req.setCharacterEncoding("UTF-8");Farmer f=new Farmer();f.setName(req.getParameter("name"));f.setFarmName(req.getParameter("farmName"));f.setEmail(req.getParameter("email"));f.setPassword(req.getParameter("password"));f.setMob(req.getParameter("mob"));f.setGender(req.getParameter("gender"));f.setAddress(req.getParameter("address"));f.setCity(req.getParameter("city"));f.setState(req.getParameter("state"));if(new FarmerDAO().saveFarmer(f)){req.getSession().setAttribute("loggedFarmer",f);res.sendRedirect(req.getContextPath()+"/welcomeFarmer.jsp");}else{req.setAttribute("errorMessage","Registration failed. Email may already be registered.");req.getRequestDispatcher("/FarmerRegistration.jsp").forward(req,res);}}}
